@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Inter', sans-serif;
}

body {
    background: #0c0634;
    color: white;
    overflow-x: hidden;
}

/* Container */
.container {
    width: 90%;
    max-width: 1400px;
    margin: auto;
}

/* Header */
header {
    position: fixed;
    width: 100%;
    z-index: 100;
    padding: 20px 0;
    background-color: #0c0634;
}

header .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    display: flex;
    align-items: center;
    gap: 12px;
}

.logo img {
    width: 150px;
}

.logo h2 {
    font-size: 20px;
}

.logo span {
    font-size: 10px;
    color: #aaa;
}

nav ul {
    display: flex;
    gap: 20px;
    list-style: none;
}

nav a {
    color: white;
    text-decoration: none;
    font-size: 14px;
    transition: .3s;
}

nav a:hover,
nav a.active {
    color: #cc2326;
}

.quote-btn {
    text-decoration: none;
    background: linear-gradient(90deg,#f2292d,#cc2326);
    color: white;
    padding: 12px 24px;
    border-radius: 8px;
    font-weight: 600;
    font-size: 14px;
}

/* Hero Slider */
.hero-slider {
    position: relative;
    width: 100%;
    height: 100vh;
    overflow: hidden;
    margin-top: 60px; /* For fixed header */
    perspective: 1000px; /* Enable 3D space */
}

.slide {
    position: absolute;
    inset: 0;
    opacity: 0;
    visibility: hidden;
    transition: 0.8s ease;
}

.slide.active {
    opacity: 1;
    visibility: visible;
}

.slide img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* 3D inner wrapper */
.slide__inner {
    position: relative;
    width: 100%;
    height: 100%;
    transform-style: preserve-3d;
    transition: transform 0.5s ease-in-out;
}

.slide__inner img {
    /* Ensure image doesn't interfere with 3D */
    pointer-events: none;
}

.content {
    position: absolute;
    top: 50%;
    left: 5%;
    transform: translateY(-50%);
    color: white;
    max-width: 500px;
    padding: 20px;
    background: rgba(0,0,0,0.4);
    border-radius: 10px;
    pointer-events: none; /* Allow mouse events to pass through to slide */
}

.content h1 {
    font-size: 2.5rem;
    margin-bottom: 15px;
    line-height: 1.2;
}

.content h1 span {
    color: #cc2326;
}

.content p {
    font-size: 1.1rem;
    line-height: 1.6;
    margin-bottom: 20px;
    color: #c8c8c8;
}

.btn {
    display: inline-block;
    background: # Add transitions for hover effects
    transition: transform 0.3s ease;
}

.btn:hover {
    background: #e32628;
    transform: translateY(-2px);
}

/* Slider Buttons */
.slider-btn {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 45px;
    height: 45px;
    border: none;
    border-radius: 50%;
    background: rgba(255,255,255,0.2);
    backdrop-filter: blur(5px);
    color: white;
    cursor: pointer;
    z-index: 100;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
}

.prev {
    left: 15px;
}

.next {
    right: 15px;
}

.slider-btn:hover {
    background: rgba(255,255,255,0.3);
}

.dots {
    position: absolute;
    bottom: 20px;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    gap: 8px;
    z-index: 100;
}

.dot {
    width: 10px;
    height: 10px;
    background: rgba(255,255,255,0.5);
    border-radius: 50%;
    cursor: pointer;
    transition: 0.3s;
}

.dot.active {
    background: white;
    transform: scale(1.2);
}

/* Partners Section */
.partners-section {
    padding: 30px 0;
    background: #f8f9ff;
    overflow: hidden;
}

.partners-section .section-title {
    text-align: center;
    font-size: 24px;
    color: #1d1d1d;
    margin-bottom: 15px;
}

.partners-track {
    display: flex;
    align-items: center;
    width: max-content;
    animation: scrollBrands 25s linear infinite;
}

.partners-track img {
    width: 100px;
    height: 50px;
    object-fit: contain;
    margin: 0 10px;
    transition: 0.3s;
}

.partners-track img:hover {
    transform: scale(1.1);
}

@keyframes scrollBrands {
    from {
        transform: translateX(0);
    }
    to {
        transform: translateX(-50%);
    }
}

/* Services Section */
.services-section {
    padding: 80px 0;
    background: #f8f9ff;
}

.services-section .section-heading {
    text-align: center;
    margin-bottom: 40px;
}

.services-section .section-heading span {
    display: inline-block;
    padding: 6px 12px;
    border-radius: 25px;
    background: #eef2ff;
    color: #6c63ff;
    font-size: 12px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.services-section .section-heading h2 {
    font-size: 2.2rem;
    margin: 10px 0;
    color: #222;
}

.services-section .section-heading p {
    max-width: 700px;
    margin: 0 auto 20px;
    color: #666;
    line-height: 1.6;
    font-size: 1rem;
}

.service-category {
    margin-bottom: 60px;
}

.service-category h3 {
    font-size: 1.8rem;
    margin-bottom: 20px;
    color: #222;
    text-align: center;
}

.services-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 20px;
}

.service-card {
    background: #fff;
    padding: 20px;
    border-radius: 15px;
    text-align: center;
    box-shadow: 0 5px 15px rgba(0,0,0,0.05);
    transition: 0.3s;
    transform-style: preserve-3d; /* Enable 3D transforms for children */
}

.service-card:hover {
    transform: translateY(-5px) rotateX(5deg) rotateY(0deg);
    box-shadow: 0 15px 30px rgba(0,0,0,0.1);
}

.service-card img {
    width: 120px;
    height: 80px;
    object-fit: contain;
    margin-bottom: 15px;
}

.service-card h4 {
    margin-bottom: 10px;
    color: #222;
    font-size: 1.1rem;
}

.service-card p {
    color: #666;
    line-height: 1.5;
    font-size: 0.9rem;
    margin-bottom: 15px;
}

.service-card a {
    text-decoration: none;
    color: #6c63ff;
    font-weight: 600;
    font-size: 0.9rem;
}

/* Why Choose Us Section */
.why-choose-section {
    position: relative;
    padding: 60px 0;
    background: linear-gradient(180deg,#f8fbff,#eef4ff);
    overflow: hidden;
}

.why-choose-section::before {
    content: "";
    position: absolute;
    width: 250px;
    height: 250px;
    background:#7c5cff20;
    border-radius:50%;
    top:-80px;
    left:-80px;
    filter:blur(30px);
}

.why-choose-section::after {
    content: "";
    position: absolute;
    width: 200px;
    height: 200px;
    background:#00d4ff15;
    border-radius:50%;
    bottom:-60px;
    right:-60px;
    filter:blur(40px);
}

.why-choose-section .section-heading {
    text-align: center;
    margin-bottom: 40px;
}

.why-choose-section .section-heading span {
    display: inline-block;
    padding: 6px 12px;
    border-radius: 25px;
    background:#eef2ff;
    color:#6c63ff;
    font-size:12px;
    font-weight:700;
    letter-spacing:1px;
    text-transform:uppercase;
}

.why-choose-section .section-heading h2 {
    font-size: 2.4rem;
    line-height:1.2;
    margin:15px 0;
    color:#202124;
    font-weight:700;
}

.why-choose-section .section-heading p {
    color:#666;
    line-height:1.6;
    font-size:1rem;
    max-width: 700px;
    margin: 0 auto 20px;
}

.why-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 25px;
}

.why-card {
    position:relative;
    background:rgba(255,255,255,.75);
    backdrop-filter:blur(10px);
    border:1px solid rgba(108,99,255,.15);
    border-radius:18px;
    padding:30px 20px;
    text-align:center;
    overflow:hidden;
    transition:.3s ease;
    box-shadow:0 10px 25px rgba(0,0,0,.05);
    transform-style: preserve-3d;
}

.why-card::before{
    content:"";
    position:absolute;
    left:0;
    top:0;
    width:100%;
    height:3px;
    background:linear-gradient(90deg,#6c63ff,#0a1436);
    transform:scaleX(0);
    transform-origin:left;
    transition:.3s;
}

.why-card::after{
    content:"";
    position:absolute;
    top:-100%;
    left:-50%;
    width:50%;
    height:200%;
    background:rgba(255,255,255,.25);
    transform:rotate(15deg);
    transition:.4s;
}

.why-card:hover{
    transform:translateY(-5px) rotateX(5deg) rotateY(0deg);
    box-shadow:0 15px 30px rgba(108,99,255,.12);
}

.why-card:hover::before{
    transform:scaleX(1);
}

.why-card:hover::after{
    left:120%;
}

.why-card i{
    width:60px;
    height:60px;
    margin:0 auto 15px;
    display:flex;
    align-items:center;
    justify-content:center;
    border-radius:50%;
    font-size:24px;
    color:#fff;
    background:linear-gradient(135deg,#6c63ff,#0a1436);
    box-shadow:0 8px 15px rgba(108,99,255,.2);
    transition:.3s;
}

.why-card:hover i{
    transform:rotateY(180deg) scale(1.05);
}

.why-card h3{
    font-size:1.2rem;
    color:#222;
    margin-bottom:10px;
}

.why-card p{
    color:#666;
    line-height:1.5;
    font-size:0.9rem;
}

/* Industries We Serve Section */
.benefit-section{
    position:relative;
    padding:60px 0;
    background:linear-gradient(135deg,#0d1b3e, #1f3c88,#0f172a);
    overflow:hidden;
}

.benefit-section::before{
    content:"";
    position:absolute;
    width:300px;
    height:300px;
    background:#6c63ff20;
    border-radius:50%;
    top:-120px;
    left:-60px;
    filter:blur(50px);
}

.benefit-section::after{
    content:"";
    position:absolute;
    width:250px;
    height:250px;
    background:#00d4ff15;
    border-radius:50%;
    bottom:-80px;
    right:-80px;
    filter:blur(50px);
}

.benefit-wrapper{
    position:relative;
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:40px;
    align-items:center;
}

.benefit-left{
    display:flex;
    flex-direction:column;
    gap:20px;
}

.benefit-item{
    display:flex;
    align-items:center;
    gap:20px;
    padding:22px;
    background:rgba(255,255,255,.06);
    border:1px solid rgba(255,255,255,.1);
    border-radius:14px;
    backdrop-filter:blur(8px);
    transition:.3s;
    transform-style: preserve-3d;
}

.benefit-item:hover{
    transform:translateX(8px) translateY(-8px) rotateX(5deg) rotateY(5deg);
    border-color:#6c63ff;
    box-shadow:0 12px 20px rgba(0,0,0,.15);
}

.benefit-icon{
    width:60px;
    height:60px;
    border-radius:50%;
    background:linear-gradient(135deg,#0d1b3e, #1f3c88);
    display:flex;
    justify-content:center;
    align-items:center;
    flex-shrink:0;
    box-shadow:0 6px 12px rgba(108,99,255,.25);
}

.benefit-icon i{
    color:#fff;
    font-size:22px;
}

.benefit-content h3{
    color:#fff;
    margin-bottom:6px;
    font-size:1.1rem;
}

.benefit-content p{
    color:#d4d8e4;
    line-height:1.5;
    font-size:0.9rem;
}

.benefit-right{
    display:flex;
    flex-direction:column;
    gap:15px;
}

.benefit-right span{
    color:#7aa8ff;
    font-weight:700;
    text-transform:uppercase;
    letter-spacing:1px;
    font-size:0.9rem;
}

.benefit-right h2{
    color:#fff;
    font-size:1.8rem;
    margin:0;
    line-height:1.2;
}

.benefit-right p{
    color:#c8d1e2;
    line-height:1.6;
    font-size:0.9rem;
}

/* CTA Section */
.cta-section{
    padding:50px 20px;
    background:#f7f9fc;
}

.cta-box{
    position:relative;
    max-width:900px;
    margin:auto;
    text-align:center;
    padding:50px 30px;
    border-radius:20px;
    background:linear-gradient(135deg,#ffffff,#f5f9ff);
