    box-shadow:0 15px 30px rgba(0,0,0,.05);
}

.cta-box::before{
    content:"";
    position:absolute;
    width:150px;
    height:150px;
    background:#6c63ff12;
    border-radius:50%;
    top:-60px;
    left:-40px;
}

.cta-box::after{
    content:"";
    position:absolute;
    width:120px;
    height:120px;
    background:#00c6ff10;
    border-radius:50%;
    bottom:-50px;
    right:-40px;
}

.cta-box>*{
    position:relative;
    z-index:2;
}

.cta-tag{
    display:inline-block;
    padding:6px 12px;
    border-radius:30px;
    background:#eef2ff;
    color:#6c63ff;
    font-size:12px;
    font-weight:700;
    letter-spacing:1px;
    text-transform:uppercase;
    margin-bottom:12px;
}

.cta-box h2{
    font-size:2rem;
    color:#1d2433;
    margin-bottom:15px;
    line-height:1.2;
}

.cta-box p{
    max-width:700px;
    margin:0 auto 25px;
    color:#6b7280;
    line-height:1.6;
    font-size:0.95rem;
}

.cta-buttons{
    display:flex;
    justify-content:center;
    gap:15px;
    flex-wrap:wrap;
}

.primary-btn{
    display:inline-flex;
    align-items:center;
    justify-content:center;
    padding:12px 25px;
    background:linear-gradient(135deg,#6c63ff,#4f46e5);
    color:#fff;
    text-decoration:none;
    border-radius:25px;
    font-weight:600;
    transition:.3s;
    box-shadow:0 6px 12px rgba(108,99,255,.2);
}

.primary-btn:hover{
    transform:translateY(-3px);
    box-shadow:0 10px 20px rgba(108,99,255,.3);
}

.secondary-btn{
    display:inline-flex;
    align-items:center;
    justify-content:center;
    padding:12px 25px;
    border:2px solid #6c63ff;
    color:#6c63ff;
    text-decoration:none;
    border-radius:25px;
    font-weight:600;
    transition:.3s;
}

.secondary-btn:hover{
    background:#6c63ff;
    color:#fff;
    transform:translateY(-3px);
}

/* Footer */
.footer {
    background: #0d1326;
    color: #fff;
    padding: 80px 0 20px;
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr 1.5fr;
    gap: 40px;
}

.footer-column h4 {
    font-size: 20px;
    margin-bottom: 25px;
    position: relative;
}

.footer-column h4::after {
    content: "";
    width: 50px;
    height: 3px;
