    transition: 0.3s;
}

.footer-column ul li a:hover {
    color: #cc2326;
    padding-left: 5px;
}

.contact-list li {
    display: flex;
    gap: 12px;
    align-items: flex-start;
    color: #cfcfcf;
}

.contact-list i {
    color: #cc2326;
    margin-top: 4px;
}

.social-links {
    display: flex;
    gap: 15px;
}

.social-links a {
