    height: 42px;
    background: rgba(255,255,255,0.1);
    color: #fff;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    text-decoration: none;
    transition: 0.3s;
}

.social-links a:hover {
    background: #cc2326;
    transform: translateY(-5px);
}

.footer-bottom {
    border-top: 1px solid rgba(255,255,255,0.1);
    margin-top: 60px;
    padding-top: 20px;
    text-align: center;
}

.footer-bottom p {
    color: #aaa;
    font-size: 14px;
}

/* Animations */
@keyframes floatIcon {
    0% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-6px);
    }
    100% {
        transform: translateY(0);
    }
}

.why-card i {
    animation: floatIcon 3s ease-in-out infinite;
}

@keyframes floatBox {
    0% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-6px);
    }
    100% {
        transform: translateY(0);
    }
}

.benefit-item {
    animation: floatBox 5s ease-in-out infinite;
}

.benefit-item:nth-child(2) {
    animation-delay: 0.5s;
}
.benefit-item:nth-child(3) {
    animation-delay: 1s;
}
.benefit-item:nth-child(4) {
    animation-delay: 1.5s;
}
.benefit-item:nth-child(5) {
    animation-delay: 2s;
}

@keyframes floatCTA {
    0% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-6px);
    }
    100% {
        transform: translateY(0);
    }
}

.cta-box {
    animation: floatCTA 5s ease-in-out infinite;
}

/* Responsive Adjustments */
@media (max-width: 768px) {
    .partners-track img {
        width: 80px;
        height: 40px;
    }

    .service-card img {
        width: 100px;
        height: 70px;
    }

    .content h1 {
        font-size: 2rem;
    }

    .content p {
        font-size: 1rem;
    }

    .why-choose-section .section-heading h2 {
        font-size: 2rem;
    }

    .benefit-right h2 {
        font-size: 1.5rem;
    }

    .cta-box h2 {
        font-size: 1.75rem;
    }
}

@media (max-width: 480px) {
    .partners-track img {
        width: 60px;
        height: 30px;
    }

    .service-card img {
        width: 80px;
        height: 50px;
    }

    .content {
        left: 5%;
        padding: 15px;
    }

    .content h1 {
        font-size: 1.5rem;
    }

    .content p {
        font-size: 0.9rem;
    }

    .btn {
        padding: 10px 20px;
        font-size: 0.9rem;
    }

    .logo img {
        width: 120px;
    }

    .logo h2 {
        font-size: 18px;
    }

    nav ul {
        gap: 10px;
    }

    nav a {
        font-size: 12px;
    }

    .quote-btn {
        padding: 10px 18px;
        font-size: 12px;
    }

    .why-choose-section .section-heading h2 {
        font-size: 1.75rem;
    }

    .benefit-right h2 {
        font-size: 1.25rem;
    }

    .cta-box h2 {
        font-size: 1.5rem;
    }

    .footer-grid {
        grid-template-columns: 1fr;
        text-align: center;
        gap: 20px;
    }

    .footer-column h4::after {
        left: 50%;
        transform: translateX(-50%);
    }

    .footer-logo {
        justify-content: center;
    }

    .contact-list {
        flex-direction: column;
        align-items: center;
    }

    .social-links {
        justify-content: center;
        margin-top: 15px;
    }
}

