// Slider functionality
const slides = document.querySelectorAll(".slide");
const dots = document.querySelectorAll(".dot");

let current = 0;

function showSlide(index){
    slides.forEach(slide =>
        slide.classList.remove("active")
    );

    dots.forEach(dot =>
        dot.classList.remove("active")
    );

    slides[index].classList.add("active");
    dots[index].classList.add("active");
}

document.querySelector(".next")
    .addEventListener("click",()=>{
        current++;
        if(current >= slides.length){
            current = 0;
        }
        showSlide(current);
    });

document.querySelector(".prev")
    .addEventListener("click",()=>{
        current--;
        if(current < 0){
            current = slides.length - 1;
        }
        showSlide(current);
    });

setInterval(()=>{
    current++;
    if(current >= slides.length){
        current = 0;
    }
    showSlide(current);
},5000);

// Observer for why-card animation (fade in on scroll)
const cards = document.querySelectorAll(".why-card");
const observer = new IntersectionObserver((entries)=>{
    entries.forEach(entry=>{
        if(entry.isIntersecting){
            element.target.classList.add("show");
        }
    });
},{
    threshold:0.25
});

cards.forEach(card=>observer.observe(card));

// 3D Enhancements
document.addEventListener('DOMContentLoaded', function() {
    // 3D tilt effect for hero slides
    slides.forEach(slide => {
        const inner = slide.querySelector('.slide__inner');
        if (!inner) return;

        // Mouse move listener for tilt effect
        slide.addEventListener('mousemove', function(e) {
            const rect = slide.getBoundingClientRect();
            const x = e.clientX - rect.left; // x position within the element
            const y = e.clientY - rect.top; // y position within the element
            const centerX = rect.width / 2;
            const centerY = rect.height / 2;
            const angleX = (y - centerY) / centerY * 10; // adjust sensitivity
            const angleY = (centerX - x) / centerX * 10; // invert x for natural feel
            // Apply transform
            inner.style.transform = `perspective(1000px) rotateX(${angleX}deg) rotateY(${angleY}deg) scale3d(1.05, 1.05, 1.05)`;
            inner.style.transition = 'transform 0.1s ease-out';
        });

        // Reset on mouse leave
        slide.addEventListener('mouseleave', function() {
            const inner = slide.querySelector('.slide__inner');
            if (inner) {
                inner.style.transform = 'perspective(1000px) rotateX(0) rotateY(0) scale3d(1, 1, 1)';
                inner.style.transition = 'transform 0.5s ease-in-out';
            }
        });
    });

    // Add subtle 3D lift to service cards on hover
    const serviceCards = document.querySelectorAll('.service-card');
    serviceCards.forEach(card => {
        card.addEventListener('mouseenter', function() {
            this.style.transform = 'translateY(-10px) rotateX(5deg) rotateY(0deg)';
            this.style.transition = 'transform 0.3s ease';
        });
        card.addEventListener('mouseleave', function() {
            this.style.transform = 'translateY(0) rotateX(0) rotateY(0)';
            this.style.transition = 'transform 0.3s ease';
        });
    });

    // Add 3D lift to why cards on hover
    const whyCards = document.querySelectorAll('.why-card');
    whyCards.forEach(card => {
        card.addEventListener('mouseenter', function() {
            this.style.transform = 'translateY(-10px) rotateX(5deg) rotateY(0deg)';
            this.style.transition = 'transform 0.3s ease';
        });
        card.addEventListener('mouseleave', function() {
            this.style.transform = 'translateY(0) rotateX(0) rotateY(0)';
            this.style.transition = 'transform 0.3s ease';
        });
    });

    // Add 3D lift to benefit items on hover
    const benefitItems = document.querySelectorAll('.benefit-item');
    benefitItems.forEach(item => {
        item.addEventListener('mouseenter', function() {
            this.style.transform = 'translateY(-8px) translateX(8px) rotateX(5deg) rotateY(5deg)';
            this.style.transition = 'transform 0.3s ease';
        });
        item.addEventListener('mouseleave', function() {
            this.style.transform = 'translateY(0) translateX(0) rotateX(0) rotateY(0)';
            this.style.transition = 'transform 0.3s ease';
        });
    });
});

